begin;
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users;
set local search_path = extensions, public, private;
select plan(18);
update private.private_locations set verified_at = now() where profile_id::text like '10000000-%';
select is((select profile_appearance from public.profiles where id='10000000-0000-0000-0000-000000000002'), '{"palette":"default","banner":"photo","effect":"none","avatarBorder":"none"}'::jsonb, 'older profiles retain default appearance');
select ok(not has_column_privilege('anon', 'public.profiles', 'profile_appearance', 'update'), 'anonymous cannot edit appearance');
select ok(has_column_privilege('authenticated', 'public.profiles', 'profile_appearance', 'update'), 'members receive the appearance column grant');
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000002', true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select set_config('request.jwt.claim.role', 'authenticated', true);
select lives_ok($$update public.profiles set profile_appearance='{"palette":"fern","banner":"aurora","effect":"fireflies","avatarBorder":"ferns"}', cover_photo_id='20000000-0000-0000-0000-000000000001' where id=auth.uid()$$, 'owner can save catalog selections beside an approved cover');
select throws_ok($$update public.profiles set profile_appearance=profile_appearance||'{"palette":"css()"}' where id=auth.uid()$$, '23514', null, 'unsupported palette rejected');
select throws_ok($$update public.profiles set profile_appearance=profile_appearance||'{"banner":"https://external.test"}' where id=auth.uid()$$, '23514', null, 'external banner URLs rejected');
select throws_ok($$update public.profiles set profile_appearance=profile_appearance||'{"effect":"unknown"}' where id=auth.uid()$$, '23514', null, 'unsupported effects rejected');
select throws_ok($$update public.profiles set profile_appearance=profile_appearance||'{"avatarBorder":"unknown"}' where id=auth.uid()$$, '23514', null, 'unsupported avatar borders rejected');
select throws_ok($$update public.profiles set profile_appearance=profile_appearance||'{"css":"body{}"}' where id=auth.uid()$$, '23514', null, 'unknown fields rejected');
select throws_ok($$update public.profiles set profile_appearance=profile_appearance-'palette' where id=auth.uid()$$, '23514', null, 'incomplete appearance rejected');
select throws_ok($$update public.profiles set profile_appearance=profile_appearance||'{"effect":null}' where id=auth.uid()$$, '23514', null, 'null catalog choices rejected');
select throws_ok($$update public.profiles set profile_appearance='[]' where id=auth.uid()$$, '23514', null, 'array appearance rejected');
select lives_ok($$update public.profiles set profile_appearance='{"palette":"ember","banner":"sunset","effect":"hearts","avatarBorder":"rainbow"}' where id='10000000-0000-0000-0000-000000000003'$$, 'another member update is filtered by RLS');
reset role;
select is((select profile_appearance->>'palette' from public.profiles where id='10000000-0000-0000-0000-000000000003'), 'default', 'another member appearance remains unchanged');
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000001', true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002')->'profile_appearance', '{"palette":"fern","banner":"aurora","effect":"fireflies","avatarBorder":"ferns"}'::jsonb, 'appearance returned only by the protected profile RPC');
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002')->>'cover_photo_id', '20000000-0000-0000-0000-000000000001', 'banner selections preserve the approved cover');
reset role;
update public.profiles set is_profile_visible=false where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002'), null::jsonb, 'hidden profile appearance remains private');
reset role;
update public.profiles set is_profile_visible=true where id='10000000-0000-0000-0000-000000000002';
insert into public.blocks(blocker_id, blocked_id) values ('10000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001');
set local role authenticated;
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002'), null::jsonb, 'blocked profile appearance remains private');
select * from finish();
rollback;
